function stepNumber(stage){return lessonOrder.indexOf(stage)+1}
const aiPollOptions=[{id:'chatgpt',label:'ChatGPT',hint:'대화·글쓰기·이미지'},{id:'gemini',label:'Gemini',hint:'Google의 AI'},{id:'claude',label:'Claude',hint:'대화·문서 작업'},{id:'none',label:'처음 써봐요',hint:'오늘 함께 시작해요'}];
let pollIdentity=null,pollChoices=[],pollBusy=false;
function loadPollIdentity(roomExpiry=state?.expiresAt){const key=`bflow-ai-poll:${session.server}:${session.code}:${roomExpiry}`;let record=null;try{record=JSON.parse(localStorage.getItem(key)||'null')}catch{}if(!record||!/^[a-f0-9]{32}$/.test(record.id||''))record={id:Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join(''),choices:[]};pollIdentity={key,id:record.id};pollChoices=Array.isArray(record.choices)?record.choices.filter(k=>aiPollOptions.some(o=>o.id===k)):[];if(pollChoices.includes('none'))pollChoices=['none'];try{localStorage.setItem(key,JSON.stringify({id:record.id,choices:pollChoices}))}catch{}}
window.addEventListener('storage',e=>{if(pollIdentity&&e.key===pollIdentity.key&&!pollBusy){loadPollIdentity();updatePoll()}});
function pollHTML(eyebrow){return `<div class="slide-inner">${eyebrow}<h2>${reviewMode?'어떤 AI를 써봤나요?':'써본 AI를 눌러주세요.'}</h2><p class="lead">${reviewMode?'수업에서 서비스 사용 경험을 함께 살펴본 화면입니다.':'여러 개 골라도 좋아요. 처음이라면 ‘처음 써봐요’를 눌러주세요.'}</p><div class="ai-poll-grid">${aiPollOptions.map((o,i)=>`<${isHost()||reviewMode?'div':'button type="button"'} class="ai-poll-card" data-poll-option="${o.id}" ${isHost()||reviewMode?'':'aria-pressed="false"'}><span class="poll-card-number">0${i+1}</span><h3>${o.label}</h3><p>${o.hint}</p><div class="poll-result"><strong data-poll-count="${o.id}">0</strong><span>명</span><small data-poll-percent="${o.id}">0%</small></div><div class="poll-bar"><span data-poll-bar="${o.id}"></span></div><span class="poll-choice-state" data-poll-check="${o.id}">${isHost()?'실시간 집계':'눌러서 선택'}</span></${isHost()||reviewMode?'div':'button'}>`).join('')}</div><div class="poll-footer"><strong id="pollRespondents" aria-live="polite">0명 응답</strong><span>여러 개 선택 · 선택 해제 가능 · 합계 비율은 100%를 넘을 수 있어요.</span></div><p id="pollStatus" class="slide-caption" role="status">${isHost()?'참여자들이 누르면 응답이 여기에 실시간으로 모입니다.':'아직 응답하지 않았어요. 선택한 내용은 이름 없이 집계됩니다.'}</p></div>`}
function updatePoll(){const poll=state?.poll||{counts:{},respondents:0};if(!$('pollRespondents'))return;if(reviewMode){renderReviewPoll('poll','pollRespondents','pollStatus');return}$('pollRespondents').textContent=`${poll.respondents}명 응답`;document.querySelectorAll('[data-poll-option]').forEach(card=>{const id=card.dataset.pollOption,selected=pollChoices.includes(id),count=poll.counts[id]||0,percent=poll.respondents?Math.round(count/poll.respondents*100):0;card.classList.toggle('selected',!isHost()&&selected);if(card.tagName==='BUTTON'){card.setAttribute('aria-pressed',String(selected));card.disabled=pollBusy||!connected}card.querySelector('[data-poll-count]').textContent=count;card.querySelector('[data-poll-percent]').textContent=percent+'%';card.querySelector('[data-poll-bar]').style.transform=`scaleX(${percent/100})`;card.querySelector('[data-poll-check]').textContent=isHost()?'실시간 집계':selected?'선택됨 ✓':'눌러서 선택'});if(!pollBusy)$('pollStatus').textContent=isHost()?'참여자들이 누르면 응답이 여기에 실시간으로 모입니다.':!connected?'연결이 복구되면 응답할 수 있습니다.':pollChoices.length?'선택을 반영했습니다. 다시 누르면 해제됩니다.':'아직 응답하지 않았어요. 선택한 내용은 이름 없이 집계됩니다.'}
function bindPoll(){document.querySelectorAll('button[data-poll-option]').forEach(button=>button.onclick=()=>submitPoll(button.dataset.pollOption));updatePoll()}
async function submitPoll(option){if(reviewMode||isHost()||pollBusy||!connected||state?.index!==slides.findIndex(s=>s.stage===0&&s.type==='idea'))return;const before=[...pollChoices];let next=before.includes(option)?before.filter(k=>k!==option):option==='none'?['none']:[...before.filter(k=>k!=='none'),option];pollBusy=true;pollChoices=next;updatePoll();$('pollStatus').textContent='응답을 반영하고 있어요…';try{const result=await api(`/api/rooms/${session.code}/poll`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({voterId:pollIdentity.id,choices:next})});try{localStorage.setItem(pollIdentity.key,JSON.stringify({id:pollIdentity.id,choices:next}))}catch{}accept(result)}catch(e){pollChoices=before;notify(e.message)}finally{pollBusy=false;updatePoll()}}
const experiencePollOptions=[{id:'ask',label:'질문·검색',hint:'궁금한 것을 물어봤어요'},{id:'writing',label:'글쓰기·요약',hint:'문구를 쓰거나 글을 줄였어요'},{id:'image',label:'이미지 제작',hint:'이미지를 만들거나 고쳤어요'},{id:'work',label:'업무·자료 정리',hint:'문서·발표·데이터에 활용했어요'},{id:'automation',label:'자동화·도구 연결',hint:'반복 작업이나 도구를 연결했어요'},{id:'none',label:'아직 처음이에요',hint:'오늘부터 함께 해볼게요'}];
