const instructionOptions={
 roles:['직장인·재직자','사무·행정 담당자','현장·기술 담당자','고객 응대·서비스 담당자','팀 운영·관리 담당자','직접 입력'],
 tasks:['업무 문서·보고서 쓰기','이메일·메시지 다듬기','공지·안내문 쓰기','홍보 콘텐츠 만들기','긴 자료 이해·요약하기','새로운 업무 배우기'],
 styles:['쉬운 말로 설명','핵심부터 짧게','단계별로 안내','예시 함께 제시','표·목록으로 정리']
};
let instructionChoice={role:'직장인·재직자',customRole:'',tasks:['업무 문서·보고서 쓰기'],styles:['쉬운 말로 설명','핵심부터 짧게']};
try{const x=JSON.parse(localStorage.getItem('bflow-instructions-v1')||'null');if(x){if(instructionOptions.roles.includes(x.role))instructionChoice.role=x.role;else if(x.role&&x.role!=='노동자'){instructionChoice.role='직접 입력';instructionChoice.customRole=String(x.role).slice(0,120)}if(typeof x.customRole==='string'&&x.customRole.trim())instructionChoice.customRole=x.customRole.slice(0,120);for(const k of ['tasks','styles'])if(Array.isArray(x[k]))instructionChoice[k]=instructionOptions[k].filter(v=>x[k].includes(v))}}catch{}
function instructionPrompt(){const c=instructionChoice,role=c.role==='직접 입력'?(c.customRole.trim()||'[나의 역할을 입력해주세요]'):c.role;return `나는 ${role}입니다.\n${c.tasks.length?'주로 '+c.tasks.join(', ')+'에 AI의 도움을 받고 싶습니다.':'도움받을 일은 대화에서 알려드리겠습니다.'}\n\n다음 기준에 맞춰 답해주세요.\n${c.styles.length?c.styles.map(t=>'• '+({'쉬운 말로 설명':'쉬운 한국어로 설명하고 전문용어는 뜻을 풀어주세요.','핵심부터 짧게':'핵심 요약을 먼저 보여주고 불필요한 설명은 줄여주세요.','단계별로 안내':'내가 따라 할 수 있도록 실행 순서를 단계별로 안내해주세요.','예시 함께 제시':'설명을 이해하고 적용할 수 있는 짧은 예시를 함께 제시해주세요.','표·목록으로 정리':'비교할 내용은 표로, 해야 할 일은 목록으로 정리해주세요.'}[t])).join('\n'):'• 질문에 알맞은 형식으로 답해주세요.'}\n• 내 업종·직무·회사 상황·전달 대상을 미리 단정하지 마세요. 답변에 꼭 필요한 정보가 없으면 먼저 물어봐주세요.\n• 확인되지 않은 사실·날짜·문의처·출처를 만들어내지 마세요. 모르면 모른다고 말해주세요.\n• 전문적인 판단이 필요한 내용은 일반 정보와 개별 판단을 구분하고, 근거와 추가 확인이 필요한 부분을 알려주세요.\n• 회사 내부 기밀·고객 정보·타인의 민감한 개인정보를 요구하지 마세요.`}
function instructionBuilder(eyebrow){const group=(key,legend,values,type)=>`<fieldset class="choice-group"><legend>${legend}<small>${type==='radio'?'하나 선택':'여러 개 선택 가능'}</small></legend><div class="choices">${values.map((v,i)=>`<label class="choice"><input type="${type}" name="instruction-${key}" value="${i}" data-choice="${key}"><span>${v}</span></label>`).join('')}</div></fieldset>`;return `<div class="slide-inner instruction-builder"><div>${eyebrow}<h2>골라보세요.<br>나만의 지침이 됩니다.</h2><p class="builder-intro">업종을 몰라도 괜찮아요. 공통 업무와 원하는 답변 방식만 골라보세요.</p>${group('role','01 나는 이런 사람이에요',instructionOptions.roles,'radio')}<label class="custom-role-label" id="customRoleLabel" hidden>나의 역할<input id="customRole" maxlength="120" placeholder="예: 현장 안전 담당자"></label>${group('tasks','02 이런 도움을 받고 싶어요',instructionOptions.tasks,'checkbox')}${group('styles','03 이렇게 답해주면 좋아요',instructionOptions.styles,'checkbox')}<button class="builder-reset" id="resetInstructions">처음 선택으로 되돌리기</button></div><div class="builder-output"><div class="prompt-card"><div class="prompt-top"><span>나만의 맞춤형 지침</span><button class="copy" data-stage="1">지침 복사 ↗</button></div><textarea id="prompt-1" readonly aria-label="01단계 맞춤형 지침"></textarea><div class="copy-status" id="status-1" role="status">선택한 내용은 이 브라우저에만 저장됩니다.</div></div><ol class="paste-steps"><li>지침 복사</li><li>ChatGPT 설정의 맞춤형 지침에 붙여넣기</li><li>새 대화에서 답변 비교하기</li></ol><div class="tools"><a href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">ChatGPT 열기 ↗</a><a href="${help[0][1]}" target="_blank" rel="noopener noreferrer">설정 도움말 ↗</a></div><p class="builder-note">메뉴가 없으면 새 대화의 첫 메시지에 붙여넣어도 돼요. 이 사이트에서 ChatGPT 설정이 자동 변경되지는 않습니다.</p></div></div>`}
function bindInstructionBuilder(){if(!$('prompt-1'))return;document.querySelectorAll('[data-choice]').forEach(el=>{const k=el.dataset.choice,v=instructionOptions[k==='role'?'roles':k][+el.value];el.checked=k==='role'?instructionChoice.role===v:instructionChoice[k].includes(v);el.onchange=()=>{if(k==='role')instructionChoice.role=v;else instructionChoice[k]=instructionOptions[k].filter((value,i)=>document.querySelector(`[data-choice="${k}"][value="${i}"]`).checked);refreshInstructions()}});$('customRole').value=instructionChoice.customRole;$('customRoleLabel').hidden=instructionChoice.role!=='직접 입력';$('customRole').oninput=()=>{instructionChoice.customRole=$('customRole').value;refreshInstructions()};$('resetInstructions').onclick=()=>{instructionChoice={role:'직장인·재직자',customRole:'',tasks:['업무 문서·보고서 쓰기'],styles:['쉬운 말로 설명','핵심부터 짧게']};bindInstructionBuilder();refreshInstructions()}}
function refreshInstructions(){$('customRoleLabel').hidden=instructionChoice.role!=='직접 입력';$('prompt-1').value=instructionPrompt();$('prompt-1').scrollTop=0;$('status-1').textContent='선택을 반영했습니다. 완성된 지침을 복사해보세요.';const b=document.querySelector('[data-stage="1"]');if(b)b.textContent='지침 복사 ↗';try{localStorage.setItem('bflow-instructions-v1',JSON.stringify(instructionChoice))}catch{$('status-1').textContent='현재 선택은 반영됐지만 브라우저 저장이 제한되어 새로고침하면 초기화될 수 있습니다.'}}
const memoryOptions={experience:['AI 사용이 처음이에요','가끔 사용하지만 아직 익숙하지 않아요','업무에 종종 활용하고 있어요'],goals:['업무 시간을 줄이고 싶어요','문서 작성 능력을 키우고 싶어요','홍보 콘텐츠를 직접 만들고 싶어요','새로운 업무를 배우고 싶어요'],details:['회의·보고 자료를 자주 준비해요','이메일·메시지를 자주 작성해요','엑셀·문서 도구를 배우고 있어요','동료에게 업무를 설명할 일이 있어요','처음 해보는 업무가 종종 생겨요','짧은 시간에 조금씩 배우고 싶어요']};
let memoryChoice={experience:'',goals:[],details:[],extra:''};
function memoryPrompt(){const m=memoryChoice,lines=[m.experience?`AI 활용 경험: ${m.experience}`:'',m.goals.length?`나의 목표: ${m.goals.join(', ')}`:'',m.details.length?`추가로 기억할 정보: ${m.details.join(', ')}`:'',m.extra.trim()?`직접 추가한 정보: ${m.extra.trim()}`:''].filter(Boolean);return lines.length?`앞으로의 대화에 참고할 수 있도록 아래 나의 정보를 기억해줘.\n\n${lines.join('\n')}\n\n내가 제공한 정보만 참고하고 업종·회사·직무·홍보 대상 등 말하지 않은 내용은 추측하지 마. 메모리 기능이 꺼져 있거나 사용할 수 없거나 저장하지 못한다면 그 점을 분명히 알려줘. 실제 저장 여부는 내가 설정의 메모리 관리 화면에서 확인할게.`:''}
function memoryBuilder(eyebrow){return `<div class="slide-inner instruction-builder memory-builder"><div>${eyebrow}<h2>나를 조금 더 알려주고,<br>기억을 부탁해요.</h2><p class="builder-intro">나에게 실제로 맞는 항목만 골라보세요. 추가 정보도 추천 항목에서 고를 수 있어요.</p><fieldset class="choice-group"><legend>01 AI에 얼마나 익숙한가요?<small>하나 선택 · 생략 가능</small></legend><div class="choices">${memoryOptions.experience.map((v,i)=>`<label class="choice"><input type="radio" name="memory-experience" data-memory="experience" value="${i}"><span>${v}</span></label>`).join('')}</div></fieldset><fieldset class="choice-group"><legend>02 앞으로 어떤 도움을 받고 싶나요?<small>여러 개 선택 가능</small></legend><div class="choices">${memoryOptions.goals.map((v,i)=>`<label class="choice"><input type="checkbox" data-memory="goals" value="${i}"><span>${v}</span></label>`).join('')}</div></fieldset><fieldset class="choice-group"><legend>03 추가 정보도 골라보세요<small>내게 맞는 것만 · 여러 개 선택</small></legend><div class="choices">${memoryOptions.details.map((v,i)=>`<label class="choice"><input type="checkbox" data-memory="details" value="${i}"><span>${v}</span></label>`).join('')}</div></fieldset><label class="memory-extra-label" for="memoryExtra">04 더 적고 싶은 내용 <small>선택 · 안 적어도 돼요</small></label><textarea id="memoryExtra" maxlength="500" rows="3" placeholder="예: 매주 팀 회의 자료를 준비해요. 요즘 엑셀을 배우고 있어요."></textarea><p class="memory-privacy">회사 기밀·고객 정보·실제 상담 내용은 넣지 마세요. 이 입력은 사이트 서버로 전송하거나 브라우저에 저장하지 않으며 새로고침하면 지워집니다.</p><button id="clearMemory" class="builder-reset">선택과 추가 정보 모두 지우기</button></div><div class="builder-output"><div class="prompt-card"><div class="prompt-top"><span>내 정보 기억 요청문</span><button class="copy" data-stage="2" disabled>기억 요청문 복사 ↗</button></div><textarea id="prompt-2" readonly aria-label="03단계 내 정보 기억 요청문" placeholder="항목을 고르거나 추가 정보를 적으면 요청문이 만들어집니다."></textarea><div class="copy-status" id="status-2" role="status">항목 하나 이상을 고르거나 추가 정보를 적어주세요.</div></div><ol class="paste-steps"><li>기억 요청문을 복사해 ChatGPT 대화에 보내기</li><li>설정의 메모리 관리에서 실제 저장 여부 확인하기</li><li>원치 않는 기억은 삭제하고 사용 여부 선택하기</li></ol><div class="tools"><a href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">ChatGPT 열기 ↗</a><a href="${help[1][1]}" target="_blank" rel="noopener noreferrer">메모리 도움말 ↗</a></div><p class="builder-note">이 사이트는 ChatGPT 메모리에 직접 저장하지 않습니다. 계정·설정에 따라 기억 기능을 사용할 수 없을 수 있어요. 메뉴가 없다면 같은 대화에서만 참고하도록 요청해 실습을 이어가세요.</p></div></div>`}
function bindMemoryBuilder(){if(!$('memoryExtra'))return;document.querySelectorAll('[data-memory]').forEach(el=>{const k=el.dataset.memory,v=memoryOptions[k][+el.value];el.checked=k==='experience'?memoryChoice.experience===v:memoryChoice[k].includes(v);el.onchange=()=>{if(k==='experience')memoryChoice.experience=v;else memoryChoice[k]=memoryOptions[k].filter((v,i)=>document.querySelector(`[data-memory="${k}"][value="${i}"]`).checked);refreshMemory()}});$('memoryExtra').value=memoryChoice.extra;$('memoryExtra').oninput=()=>{memoryChoice.extra=$('memoryExtra').value;refreshMemory()};$('clearMemory').onclick=()=>{memoryChoice={experience:'',goals:[],details:[],extra:''};bindMemoryBuilder();refreshMemory()};const b=document.querySelector('[data-stage="2"]');b.disabled=!memoryPrompt()}
function refreshMemory(){const text=memoryPrompt();$('prompt-2').value=text;$('prompt-2').scrollTop=0;const b=document.querySelector('[data-stage="2"]');b.disabled=!text;b.textContent='기억 요청문 복사 ↗';$('status-2').textContent=text?'요청문을 만들었습니다. 아직 ChatGPT에 보내거나 기억을 저장한 것은 아닙니다.':'항목 하나 이상을 고르거나 추가 정보를 적어주세요.'}
const designOptions={mood:['깔끔하고 단정하게','따뜻하고 친근하게','전문적이고 신뢰감 있게','밝고 활기차게'],background:['밝은 베이지','깨끗한 흰색','차분한 네이비','은은한 파스텔','직접 색상 선택'],layout:['제목을 더 크게','여백을 더 넓게','정보를 중앙에 모으기','안내 문구를 하단에 정리'],visual:['그림을 조금 작게','그림을 조금 크게','그림 위치를 오른쪽으로','그림을 빼고 글자 중심으로']};
let designChoice={mood:'',background:'',layout:'',visual:'',color:'#e9e1fa',extra:''};
try{const d=JSON.parse(localStorage.getItem('bflow-design-edit-v1')||'null');if(d){for(const k of Object.keys(designOptions))if(designOptions[k].includes(d[k]))designChoice[k]=d[k];if(/^#[a-f0-9]{6}$/i.test(d.color||''))designChoice.color=d.color;if(typeof d.extra==='string')designChoice.extra=d.extra.slice(0,500)}}catch{}
function designPrompt(){const d=designChoice,changes=[d.mood?`전체 분위기: ${d.mood}`:'',d.background?`배경색: ${d.background==='직접 색상 선택'?d.color:d.background}`:'',d.layout?`글자와 배치: ${d.layout}`:'',d.visual?`그림과 크기: ${d.visual}`:'',d.extra.trim()?`추가 수정 요청: ${d.extra.trim()}`:''].filter(Boolean);if(!changes.length)return '';const topic=brief.topic&&brief.topic!=='아직 정하지 않았음'?`'${brief.topic}' 홍보 이미지`:'방금 만든 홍보 이미지';return `${topic}를 아래 요청대로 수정해줘.\n\n${changes.map(t=>'• '+t).join('\n')}\n\n요청한 부분을 우선 수정하고, 그 밖의 요소는 가능한 한 유지해줘. 확정한 제목·문구·숫자·날짜·장소·문의처는 바꾸거나 새로 만들지 마. 읽기 쉬운 글자 크기와 대비를 확보해줘. 수정 후 다른 부분이나 이미지 속 글자가 달라졌는지 내가 확인할 점검 항목도 알려줘.`}
function designBuilder(eyebrow){const fields=[['mood','분위기'],['background','배경색'],['layout','글자와 배치'],['visual','그림과 크기']];return `<div class="slide-inner instruction-builder design-builder"><div>${eyebrow}<h2>원하는 디자인으로,<br>내가 골라 수정해요.</h2><p class="builder-intro">바꾸고 싶은 항목만 고르세요. 선택하지 않은 부분은 유지하도록 요청합니다.</p><div class="design-fields">${fields.map(([key,title])=>`<label>${title}<select data-design="${key}" aria-label="${title}"><option value="">선택하지 않음</option>${designOptions[key].map((v,i)=>`<option value="${i}">${v}</option>`).join('')}</select></label>`).join('')}</div><label id="designColorLabel" class="design-color" hidden>원하는 배경색<input type="color" id="designColor" value="#e9e1fa"><span id="designColorValue">#e9e1fa</span></label><label class="memory-extra-label" for="designExtra">내가 원하는 수정 <small>선택 · 500자 이내</small></label><textarea id="designExtra" maxlength="500" rows="3" placeholder="예: 제목을 두 줄로 나누고, 그림은 오른쪽 아래로 옮겨줘. 파란색은 그대로 유지해줘."></textarea><button id="resetDesign" class="builder-reset">선택과 추가 요청 지우기</button><div class="tools"><button class="brief-button">홍보 주제 입력하기</button><a href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">ChatGPT 열기 ↗</a></div></div><div class="builder-output"><div class="prompt-card"><div class="prompt-top"><span>나만의 이미지 수정 요청문</span><button class="copy" data-stage="7" disabled>수정 요청문 복사 ↗</button></div><textarea id="prompt-7" readonly aria-label="08단계 이미지 수정 요청문" placeholder="원하는 디자인을 선택하거나 수정할 내용을 적어주세요."></textarea><div class="copy-status" id="status-7" role="status">한 가지 이상 고르거나 직접 요청을 적어주세요.</div></div><ol class="paste-steps"><li>원하는 디자인을 고르고 요청문 복사하기</li><li>이미지를 만든 ChatGPT 대화에 붙여넣기</li><li>수정된 이미지의 글자·정보·다른 부분 확인하기</li></ol><p class="builder-note">여기서는 수정 요청문만 만듭니다. 실제 이미지 수정은 ChatGPT에서 실행해요. 선택한 곳 외에도 바뀔 수 있으며, 기능과 사용 한도는 계정마다 다를 수 있습니다.</p></div></div>`}
function bindDesignBuilder(){if(!$('designExtra'))return;document.querySelectorAll('[data-design]').forEach(el=>{const key=el.dataset.design,index=designOptions[key].indexOf(designChoice[key]);el.value=index<0?'':String(index);el.onchange=()=>{designChoice[key]=el.value===''?'':designOptions[key][Number(el.value)];refreshDesign()}});$('designExtra').value=designChoice.extra;$('designExtra').oninput=()=>{designChoice.extra=$('designExtra').value;refreshDesign()};$('designColor').value=designChoice.color;$('designColor').oninput=()=>{designChoice.color=$('designColor').value;refreshDesign()};$('resetDesign').onclick=()=>{designChoice={mood:'',background:'',layout:'',visual:'',color:'#e9e1fa',extra:''};bindDesignBuilder();refreshDesign()};$('designColorLabel').hidden=designChoice.background!=='직접 색상 선택';$('designColorValue').textContent=designChoice.color;document.querySelector('[data-stage="7"]').disabled=!designPrompt()}
