const storageKey='bflow-live-session-v2';let viewGeneration=0,reviewMode=false;let instructorNotes=null,instructorCover=null;let session=null,state=null,source=null,connected=false,currentIndex=0,syncing=false,scrollTimer,requesting=false,ended=false;
