function finish(message){viewGeneration++;window.dispatchEvent(new Event('classroom:ended'));ended=true;connected=false;source?.close();source=null;instructorNotes=null;instructorCover=null;session=null;state=null;try{sessionStorage.removeItem(storageKey)}catch{};$('shareDialog').close();$('notesContent').replaceChildren();$('notes').hidden=true;$('notesToggle').hidden=true;$('deck').innerHTML='';showWaiting(message);setConnection('수업 종료');$('prev').disabled=true;$('next').disabled=true;for(const id of ['timerStart','timerReset','durationLabel','timerApply'])$(id).hidden=true;$('clock').textContent='—';$('openSession').textContent='새 수업 연결'}
async function connect(){const generation=++viewGeneration;reviewMode=false;document.body.classList.remove('review-mode');$('reviewNavigation').hidden=true;window.dispatchEvent(new Event('classroom:ended'));history.replaceState(null,'',location.pathname+location.hash);ended=false;instructorNotes=null;instructorCover=null;$('notesContent').replaceChildren();$('notes').hidden=true;$('notesToggle').hidden=true;state=null;$('deck').replaceChildren();source?.close();setConnection('수업 연결 중…');try{const next=await api(`/api/rooms/${session.code}`);if(generation!==viewGeneration)return false;if(isHost()){const data=await api(`/api/rooms/${session.code}/notes`,{headers:{Authorization:`Bearer ${session.token}`}});if(generation!==viewGeneration)return false;instructorNotes=data.notes;instructorCover=data.cover}const content=await import(`${session.server}/api/rooms/${session.code}/content.js`);if(generation!==viewGeneration)return false;if(!Array.isArray(content.steps)||content.steps.length!==9||!content.steps.every(s=>typeof s.prompt==='function')||!Array.isArray(content.help))throw Error('강의 자료를 불러오지 못했습니다.');steps=content.steps;help=content.help;lessonOrder=content.lessonOrder;if(!Array.isArray(lessonOrder)||lessonOrder.length!==9||new Set(lessonOrder).size!==9||lessonOrder.some(i=>!Number.isInteger(i)||i<0||i>=9))throw Error('강의 순서를 불러오지 못했습니다.');slides=content.slidePlan;if(!Array.isArray(slides)||slides.length!==30||slides.some(s=>!s||!Number.isInteger(s.stage)||s.stage<0||s.stage>=9||!['cover','idea','experience','do','prompt','closing'].includes(s.type)))throw Error('강의 화면을 불러오지 못했습니다.');loadPollIdentity(next.expiresAt);loadExperienceIdentity(next.expiresAt);connected=true;accept(next);saveSession();window.dispatchEvent(new Event('classroom:connected'));$('sessionDialog').close();source=new EventSource(`${session.server}/api/rooms/${session.code}/events`);source.onmessage=e=>{if(generation!==viewGeneration)return;try{connected=true;setConnection(`${isHost()?'강사':'참여자'} · ${session.code}`,true);accept(JSON.parse(e.data));updateUI()}catch{}};source.onerror=()=>{if(generation!==viewGeneration)return;connected=false;setConnection('연결 복구 중 · 다음 화면 잠김');updateUI();checkRoom()};return true}catch(e){if(generation!==viewGeneration)return false;connected=false;setConnection('연결 실패');showWaiting('수업 연결을 확인해주세요.');throw e}}
window.addEventListener('offline',()=>{if(reviewMode||!session)return;connected=false;source?.close();setConnection('오프라인 · 다음 화면 잠김');updateUI()});
window.addEventListener('online',()=>{if(!reviewMode&&session)connect().catch(e=>notify(e.message))});
let roomCheckBusy=false;async function checkRoom(){if(roomCheckBusy||!session)return;roomCheckBusy=true;try{const s=await api(`/api/rooms/${session.code}`);if(s.ended)finish('수업이 종료되었습니다.')}catch(e){if(e.message.includes('종료'))finish(e.message)}finally{roomCheckBusy=false}}
function showWaiting(title='같은 속도로, 함께 배워요.'){const section=document.createElement('section');section.className='waiting';const content=document.createElement('div');const label=document.createElement('span');label.className='eyebrow';label.textContent='BFLOW LIVE CLASS';const h=document.createElement('h1');h.textContent=title;const p=document.createElement('p');p.textContent='강사는 새 수업을 시작하고, 참여자는 전달받은 주소나 코드로 입장하세요.';const b=document.createElement('button');b.className='primary';b.textContent='수업 연결하기 →';b.onclick=()=>$('sessionDialog').showModal();content.append(label,h,p,b);section.append(content);$('deck').replaceChildren(section)}
$('openSession').onclick=()=>{if(reviewMode){$('sessionDialog').showModal();return}if(isHost()){const url=new URL(session.server+'/');url.hash='join='+session.code;$('shareUrl').value=url.href;$('shareCode').textContent=session.code;try{const qr=qrcode(0,'M');qr.addData(url.href);qr.make();$('roomQr').src=qr.createDataURL(6,24);$('roomQr').hidden=false;$('qrStatus').textContent='휴대폰 카메라로 스캔하면 바로 입장합니다.'}catch{$('roomQr').hidden=true;$('qrStatus').textContent='QR을 만들지 못했습니다. 참여 주소나 숫자 코드를 공유해주세요.'}$('shareDialog').showModal()}else $('sessionDialog').showModal()};
$('copyShare').onclick=()=>copy($('shareUrl'),null,$('copyShare'));
$('createRoom').onclick=async()=>{const btn=$('createRoom');if(session&&!confirm('현재 수업 화면을 떠나 새 수업을 만들까요? 기존 수업은 자동 종료되지 않습니다.'))return;btn.disabled=true;try{const server=endpoint();const res=await fetch(server+'/api/rooms',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}',signal:AbortSignal.timeout(15000)});const data=await res.json();if(!res.ok)throw Error(data.error||'수업을 만들 수 없습니다. 서버 주소와 연결 상태를 확인하세요.');session={server,code:data.code,token:data.hostToken,role:'host'};await connect();$('openSession').click()}catch(e){$('sessionError').textContent=e.message}finally{btn.disabled=false}};
$('joinRoom').onclick=async()=>{const code=$('roomCode').value.replace(/\s|-/g,'').toUpperCase();if(!/^[0-9]{6}$/.test(code)){$('sessionError').textContent='숫자 6자리 참여 코드를 확인하세요.';return}const btn=$('joinRoom');btn.disabled=true;try{session={server:endpoint(),code,role:'student'};await connect();history.replaceState(null,'',location.pathname+location.search+'#join='+code)}catch(e){$('sessionError').textContent=e.message}finally{btn.disabled=false}};
$('endRoom').onclick=()=>{if(confirm('참여자 연결을 종료할까요? 종료 후에는 새 수업이 필요합니다.'))control({action:'end'})};
$('notesToggle').onclick=()=>{if(canReadNotes())$('notes').hidden=!$('notes').hidden};$('closeNotes').onclick=()=>$('notes').hidden=true;
Object.keys(brief).forEach(k=>{$(k).value=brief[k];$(k).oninput=()=>{brief[k]=$(k).value;updatePrompts();try{localStorage.setItem('bflow-brief-v2',JSON.stringify(brief))}catch{notify('저장이 제한되어 새로고침하면 입력이 사라질 수 있습니다.')}}});$('briefDone').onclick=()=>$('briefDialog').close();$('clearBrief').onclick=()=>{Object.keys(brief).forEach(k=>{brief[k]='';$(k).value=''});try{localStorage.removeItem('bflow-brief-v2')}catch{}updatePrompts();notify('내 입력을 지웠습니다.')};
let lastDuration=null;function tick(){if(reviewMode||!state?.timer)return;const t=state.timer,left=t.end?Math.max(0,Math.ceil((t.end-Date.now())/1000)):t.remaining;$('clock').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;$('timerStart').textContent=t.end&&left>0?'정지':left===0?'다시 시작':'시작';$('timerStart').disabled=!connected;$('timerReset').disabled=!connected;$('timerApply').disabled=!connected;if(lastDuration!==t.duration){$('duration').value=t.duration/60;lastDuration=t.duration}}
setInterval(tick,250);$('timerStart').onclick=()=>control({action:'timer',command:state.timer.end&&state.timer.end>Date.now()?'pause':'start'});$('timerReset').onclick=()=>control({action:'timer',command:'reset'});$('timerApply').onclick=()=>{const minutes=Number($('duration').value);if(!Number.isInteger(minutes)||minutes<1||minutes>180){notify('1~180 사이의 정수 분을 입력하세요.');return}control({action:'timer',command:'set',minutes})};
function renderReviewPoll(prefix,countId,statusId){$(countId).textContent='수업 중 함께한 설문';$(statusId).textContent='복습 자료에서는 설문을 새로 집계하거나 과거 응답을 표시하지 않습니다.';document.querySelectorAll(`[data-${prefix}-option]`).forEach(card=>{card.classList.remove('selected');card.querySelector('.poll-result').hidden=true;card.querySelector('.poll-bar').hidden=true;card.querySelector(`[data-${prefix}-check]`).textContent='수업용 설문 항목'})}
function saveReviewPosition(){history.replaceState(null,'',location.pathname+'?review=1&slide='+(currentIndex+1))}
async function beginReview(){const generation=++viewGeneration;window.dispatchEvent(new Event('classroom:ended'));source?.close();source=null;reviewMode=true;session=null;connected=false;state=null;ended=false;instructorNotes=null;instructorCover=null;$('notesContent').replaceChildren();$('notes').hidden=true;$('notesToggle').hidden=true;$('sessionDialog').close();$('shareDialog').close();$('deck').replaceChildren();document.body.classList.add('review-mode');setConnection('참여자 복습 자료');try{const content=await import(new URL('review-content.js',location.href).href);if(generation!==viewGeneration||!reviewMode)return;steps=content.steps;help=content.help;lessonOrder=content.lessonOrder;slides=content.slidePlan;if(!Array.isArray(steps)||steps.length!==9||!Array.isArray(slides)||slides.length!==30)throw Error('강의 자료 형식을 확인할 수 없습니다.');$('reviewJump').replaceChildren();slides.forEach((slide,i)=>{const option=document.createElement('option');option.value=i;const kind={idea:slide.stage===0?'AI 서비스 설문':'핵심 설명',experience:'AI 활용 범위 설문',do:'실습 순서',prompt:'프롬프트'};option.textContent=`${i+1}. ${slide.type==='cover'?'강의 시작':slide.type==='closing'?'감사합니다':`${steps[slide.stage].short} · ${kind[slide.type]}`}`;$('reviewJump').append(option)});state={index:0,maxIndex:slides.length-1,revision:0};render();$('reviewNavigation').hidden=false;const requested=Number(new URLSearchParams(location.search).get('slide'));move(Number.isInteger(requested)&&requested>=1&&requested<=slides.length?requested-1:0,'instant')}catch(e){if(generation!==viewGeneration)return;showWaiting('강의 자료를 불러오지 못했습니다.');notify('새로고침해 다시 확인해주세요. '+e.message)}}
$('openReview').onclick=beginReview;$('reviewJump').onchange=()=>move(Number($('reviewJump').value));
(async()=>{showWaiting('강의 자료를 준비하고 있어요.');try{session=JSON.parse(sessionStorage.getItem(storageKey)||'null')}catch{}if(!session||!['host','student'].includes(session.role)||!session.server||!session.code)session=null;const params=new URLSearchParams(location.hash.slice(1)),code=params.get('join'),review=new URLSearchParams(location.search).get('review')==='1';const isStatic=location.hostname.endsWith('github.io');$('serverField').hidden=!isStatic;$('serverUrl').value=session?.server||(!isStatic?location.origin:'');if(review||(!code&&!session)){await beginReview();return}history.replaceState(null,'',location.pathname+location.hash);if(code&&/^[0-9]{6}$/.test(code)){if(!session||session.code!==code)session={server:!isStatic?location.origin:session?.server,code,role:'student'};$('roomCode').value=code}if(session?.server){try{await connect();return}catch(e){$('sessionError').textContent=e.message;if(!code){await beginReview();return}}}if(isStatic&&!$('serverUrl').value)$('sessionError').textContent='실시간 수업은 강사가 발급한 서버의 참여 주소로 접속해주세요.';$('sessionDialog').showModal()})();
